package dev.mineagent.runtime.neoforge.ui;
import dev.mineagent.runtime.core.memory.*;import dev.mineagent.runtime.neoforge.MineAgentRuntimeServices;import net.minecraft.server.MinecraftServer;import java.nio.file.Path;import java.time.Clock;import java.util.*;import java.util.concurrent.*;import java.util.function.*;
/** Small query deadline; versioned background indexing never waits for a chat summary or world action. */
public final class ServerMemoryRecall {
 private static final ExecutorService IO=Executors.newVirtualThreadPerTaskExecutor();private static final Map<String,Long> INDEXING=new ConcurrentHashMap<>();private static final Semaphore INDEX_SLOTS=new Semaphore(2);private static final Map<String,double[]> QUERIES=Collections.synchronizedMap(new LinkedHashMap<>());
 private record Scope(MinecraftServer server,Path db,UUID world,UUID owner,UUID agent,String model,BooleanSupplier permit){}
 private static List<SemanticMemoryIndex.Document> documents(Scope s)throws Exception{var docs=new ArrayList<SemanticMemoryIndex.Document>();try(var memory=new DialogueMemoryStore(s.db(),s.world(),s.owner(),s.agent(),Clock.systemUTC())){for(var e:memory.activeEntries())docs.add(new SemanticMemoryIndex.Document("dialogue",e.id(),e.revision(),e.kind()+" "+e.topic()+" "+e.value()+" "+String.join(" ",e.aliases()),e.updatedAt(),e.source()));}for(var e:MineAgentRuntimeServices.memories(s.server()).visibleTo(s.owner(),false))docs.add(new SemanticMemoryIndex.Document("shared",e.memoryId(),e.revision(),e.kind()+" "+e.key()+" "+e.value(),e.updatedAtEpochMillis(),"world_note"));return docs;}
 public static CompletableFuture<String> recall(MinecraftServer server,UUID owner,UUID agent,String query,int budget,BooleanSupplier permit){var config=MineAgentRuntimeServices.config(server);var values=config.snapshot().values();String model=values.getOrDefault("provider.openai.role.embedding","").strip(),base=values.getOrDefault("provider.openai.baseUrl","");var scope=new Scope(server,server.getServerDirectory().resolve("mineagent-runtime-data/runtime.db"),MineAgentRuntimeServices.worldId(server),owner,agent,base+"|"+model,permit);
  var prepared=CompletableFuture.supplyAsync(()->{try{return documents(scope);}catch(Exception e){throw new CompletionException(e);}},IO);
  return prepared.thenCompose(docs->{if(model.isBlank()||docs.isEmpty())return context(scope,query,budget,Map.of(),"LEXICAL_ONLY");index(scope,docs);String queryKey=scope.world()+"|"+owner+"|"+agent+"|"+scope.model()+"|"+query;double[] cached=QUERIES.get(queryKey);CompletableFuture<double[]> embedding=cached!=null?CompletableFuture.completedFuture(cached):MineAgentRuntimeServices.worker(server).embedMemory(config,scope.world(),agent,List.of(query),permit).thenApply(reply->{var vectors=vectors(reply);if(vectors.size()!=1)throw new IllegalStateException("MEMORY_QUERY_VECTOR_COUNT");var vector=vectors.getFirst();synchronized(QUERIES){QUERIES.put(queryKey,vector);while(QUERIES.size()>128)QUERIES.remove(QUERIES.keySet().iterator().next());}return vector;});
   return embedding.thenApply(vector->vector).completeOnTimeout(null,1500,TimeUnit.MILLISECONDS).exceptionally(error->null).thenCompose(vector->{if(vector==null)return context(scope,query,budget,Map.of(),"LEXICAL_FALLBACK_VECTOR_UNAVAILABLE");return CompletableFuture.supplyAsync(()->{try(var index=new SemanticMemoryIndex(scope.db(),scope.world(),owner,agent)){var fresh=documents(scope);return SemanticMemoryIndex.similarities(fresh,index.vectors(fresh,scope.model()),vector);}catch(Exception e){throw new CompletionException(e);}},IO).thenCompose(scores->context(scope,query,budget,scores,scores.isEmpty()?"LEXICAL_WHILE_INDEXING":"HYBRID_KEYWORD_SEMANTIC"));});
  });
 }
 private static CompletableFuture<String> context(Scope s,String query,int budget,Map<String,Double> scores,String mode){return CompletableFuture.supplyAsync(()->{try(var memory=new DialogueMemoryStore(s.db(),s.world(),s.owner(),s.agent(),Clock.systemUTC())){if(!s.permit().getAsBoolean())throw new IllegalStateException("CONVERSATION_CANCELLED");String body=memory.context(query,budget,scores)+MineAgentRuntimeServices.memories(s.server()).context(s.owner(),query,2000,scores);return body.isEmpty()?"":"[记忆检索方式："+mode+"；向量仅用于排序，不是事实证明。]\n"+body;}catch(Exception e){throw new CompletionException(e);}},IO);}
 private static void index(Scope s,List<SemanticMemoryIndex.Document> docs){String key=s.world()+"|"+s.owner()+"|"+s.agent()+"|"+s.model();long now=System.currentTimeMillis();Long last=INDEXING.putIfAbsent(key,now);if(last!=null){if(now-last<30000)return;if(!INDEXING.replace(key,last,now))return;}if(!INDEX_SLOTS.tryAcquire()){INDEXING.remove(key,now);return;}
  CompletableFuture.supplyAsync(()->{try(var index=new SemanticMemoryIndex(s.db(),s.world(),s.owner(),s.agent())){var existing=index.vectors(docs,s.model());return docs.stream().filter(d->!existing.containsKey(d.origin()+"_"+d.id())).sorted(Comparator.comparingLong(SemanticMemoryIndex.Document::updatedAt).reversed()).limit(8).toList();}catch(Exception e){throw new CompletionException(e);}},IO).thenCompose(missing->{if(missing.isEmpty())return CompletableFuture.completedFuture(true);return MineAgentRuntimeServices.worker(s.server()).embedMemory(MineAgentRuntimeServices.config(s.server()),s.world(),s.agent(),missing.stream().map(SemanticMemoryIndex.Document::text).toList(),s.permit()).thenApplyAsync(reply->{try(var index=new SemanticMemoryIndex(s.db(),s.world(),s.owner(),s.agent())){var vectors=vectors(reply);if(vectors.size()!=missing.size())throw new IllegalStateException("MEMORY_VECTOR_COUNT");var fresh=documents(s);for(int i=0;i<missing.size();i++){var d=missing.get(i);if(fresh.stream().anyMatch(v->v.id().equals(d.id())&&v.origin().equals(d.origin())&&v.revision()==d.revision()))index.save(d,s.model(),vectors.get(i));}return true;}catch(Exception e){throw new CompletionException(e);}},IO);}).whenComplete((v,error)->{INDEX_SLOTS.release();if(error==null)INDEXING.remove(key);});
 }
 private static List<double[]> vectors(dev.mineagent.runtime.api.worker.WorkerEnvelope reply){if(!reply.type().equals("embedding.result")||!(reply.payload().get("vectors") instanceof List<?> rows))throw new IllegalStateException("MEMORY_EMBEDDING_UNAVAILABLE");var out=new ArrayList<double[]>();for(var row:rows){if(!(row instanceof List<?> values))throw new IllegalArgumentException("MEMORY_VECTOR_FORMAT");var vector=new double[values.size()];for(int i=0;i<vector.length;i++){if(!(values.get(i) instanceof Number n)||!Double.isFinite(n.doubleValue()))throw new IllegalArgumentException("MEMORY_VECTOR_VALUE");vector[i]=n.doubleValue();}out.add(vector);}return out;}
 private ServerMemoryRecall(){}
}
